-- Generated by npm run art:avatar from avatar-art/. Do not edit by hand.
-- Upserts the avatar v2 catalog. Safe to run repeatedly.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM public.avatar_items WHERE art_version = 1 AND item_key IN ('base_body', 'brows_scowl', 'brows_soft', 'buckle_boots', 'charm_choker', 'eyes_hollow', 'eyes_sleepless', 'eyes_wide', 'grave_creepers', 'grave_tee', 'gravewarden_cloak', 'hair_long_wisp', 'hex_stockings', 'katana_back', 'katana_drawn', 'mouth_fang', 'mouth_smile', 'mouth_stitched', 'paint_blush', 'paint_stitches', 'patched_trousers', 'porcelain_mask', 'ram_horns', 'soul_lantern', 'stitchwork_sweater', 'tattered_bat_wings', 'tattered_skirt', 'witch_hat')) THEN
        RAISE EXCEPTION 'An avatar-art item_key clashes with a legacy avatar item';
    END IF;
END $$;

